### <strong>Custom Authentication Failure Handler</strong>

- <strong>예시) Custom Authentication Failure Handler</strong>
    <a id="1c3eda9b0fe1810ca8f7c9df47d29a8b"></a>

    ```java
    @Component
    public class CustomAuthenticationFailureHandler extends SimpleUrlAuthenticationFailureHandler {

        @Override
        public void onAuthenticationFailure(HttpServletRequest request, HttpServletResponse response, AuthenticationException exception) throws IOException, ServletException {
            String errorMessage = "Invalid username or password";

            if (exception instanceof UsernameNotFoundException) {
                errorMessage = "User not found";
            } else if (exception instanceof BadCredentialsException) {
                errorMessage = "Invalid username or password";
            } else if (exception instanceof LockedException) {
                errorMessage = "Your account has been locked";
            } else if (exception instanceof DisabledException) {
                errorMessage = "Your account is disabled";
            } else if (exception instanceof AccountExpiredException) {
                errorMessage = "Your account has expired";
            } else if (exception instanceof CredentialsExpiredException) {
                errorMessage = "Your credentials have expired";
            }

            response.sendRedirect("/login?error=" + errorMessage);
        }
    }
    ```

- <strong>예시) the Custom Authentication Failure Handler 사용하기 위한 구성</strong>
    <a id="1c3eda9b0fe181adb06ec7447b6deb02"></a>

    ```java
    @Configuration
    @EnableWebSecurity
    public class WebSecurityConfig extends WebSecurityConfigurerAdapter {

        @Autowired
        private CustomUserDetailsService userDetailsService;

        @Autowired
        private CustomAuthenticationFailureHandler customAuthenticationFailureHandler;

        @Override
        protected void configure(AuthenticationManagerBuilder auth) throws Exception {
            auth.userDetailsService(userDetailsService).passwordEncoder(new BCryptPasswordEncoder());
        }

        @Override
        protected void configure(HttpSecurity http) throws Exception {
            http
                .authorizeRequests()
                    .anyRequest().authenticated()
                    .and()
                .formLogin()
                    .loginPage("/login")
                    .failureHandler(customAuthenticationFailureHandler)
                    .permitAll()
                    .and()
                .logout()
                    .permitAll();
        }
    }
